SELECT dept_name, CASE WHEN budget >= 3656000 THEN 'high' WHEN budget >= 1176000 THEN 'mid' ELSE 'low' END budget_bucket, CASE WHEN location IN ('London', 'Tokyo') THEN 'group_a' ELSE 'other' END location_group, COUNT(CASE WHEN location = 'Tokyo' THEN 1 END) tokyo_count FROM departments WHERE (dept_name = 'Engineering' AND budget BETWEEN 1812000 AND 3373000) OR budget < 3383000 GROUP BY 1, 2, 3 ORDER BY location_group DESC, tokyo_count;
